/**
 * App-local bearer-token auth for the per-meter readings ingest path.
 *
 * Physical energy meters POST readings to `POST /api/readings` with
 * `Authorization: Bearer <token>`. The token is a 32-char base64url string
 * generated by `POST /api/meters/:id/tokens` and shown to the user ONCE; only
 * its SHA-256 hex digest is persisted in `meter_tokens.token_hash`.
 *
 * Verification:
 *   1. Look up the row by `token_hash` (single-row indexed lookup).
 *   2. Compare digests via `crypto.timingSafeEqual` to defeat timing oracles.
 *   3. Reject if `enabled = false` or `revoked_at IS NOT NULL`.
 *   4. Stash `meter_id` + `user_id` on `res.locals.meterAuth` so the
 *      readings handler can persist with the correct ownership without
 *      trusting a body-supplied `meter_id`.
 *
 * **Not** a candidate for the molecule bond system — this is normal app-level
 * resource auth, scoped to one ingest endpoint, and the design note in
 * `INVENTORY.md` already records that decision.
 *
 * @module
 */
import { createHash, randomBytes, timingSafeEqual } from 'node:crypto'

import type { NextFunction, Request, RequestHandler, Response } from 'express'

import { findMany, updateById } from '@molecule/api-database'
import { t } from '@molecule/api-i18n'

const TOKEN_BYTES = 24 // base64url(24) → 32 chars
const TOKEN_HASH_HEX_LEN = 64 // sha256 hex digest length

/** Random 32-char base64url string. Kept small enough to fit on a meter's display. */
export function generateMeterToken(): string {
  return randomBytes(TOKEN_BYTES).toString('base64url')
}

/** SHA-256 hex digest of a plaintext token, used for both lookup and comparison. */
export function hashMeterToken(plaintext: string): string {
  return createHash('sha256').update(plaintext).digest('hex')
}

/**
 * Constant-time comparison of two hex digests of the same length.
 * Returns `false` (not throwing) on length mismatch so the row-lookup
 * path can keep its short-circuit semantics.
 */
function safeHexEq(a: string, b: string): boolean {
  if (a.length !== b.length || a.length !== TOKEN_HASH_HEX_LEN) return false
  try {
    return timingSafeEqual(Buffer.from(a, 'hex'), Buffer.from(b, 'hex'))
  } catch (_error) {
    // buffer construction failed — treat as mismatch
    return false
  }
}

export interface MeterAuthLocals {
  meterId: string
  userId: string
  tokenId: string
}

declare module 'express-serve-static-core' {
  interface Locals {
    meterAuth?: MeterAuthLocals
  }
}

/**
 * Express middleware. Reads `Authorization: Bearer <token>`; on success,
 * sets `res.locals.meterAuth = { meterId, userId, tokenId }` and calls next().
 * On any failure, responds 401 (no body leak about which step failed).
 */
export const requireMeterToken: RequestHandler = async (
  req: Request,
  res: Response,
  next: NextFunction,
): Promise<void> => {
  const header = req.headers.authorization
  if (!header || !header.startsWith('Bearer ')) {
    res.status(401).json({
      error: t('readings.invalidToken', undefined, { defaultValue: 'Invalid meter token.' }),
    })
    return
  }
  const token = header.slice('Bearer '.length).trim()
  if (token.length === 0) {
    res.status(401).json({
      error: t('readings.invalidToken', undefined, { defaultValue: 'Invalid meter token.' }),
    })
    return
  }

  const candidateHash = hashMeterToken(token)
  try {
    const rows = await findMany<{
      id: string
      meter_id: string
      user_id: string
      token_hash: string
      enabled: boolean
      revoked_at: Date | null
    }>('meter_tokens', {
      where: [{ field: 'token_hash', operator: '=', value: candidateHash }],
      limit: 1,
    })
    const row = rows[0]
    if (!row || !row.enabled || row.revoked_at) {
      res.status(401).json({
        error: t('readings.invalidToken', undefined, { defaultValue: 'Invalid meter token.' }),
      })
      return
    }
    if (!safeHexEq(row.token_hash, candidateHash)) {
      res.status(401).json({
        error: t('readings.invalidToken', undefined, { defaultValue: 'Invalid meter token.' }),
      })
      return
    }

    res.locals.meterAuth = {
      meterId: row.meter_id,
      userId: row.user_id,
      tokenId: row.id,
    }

    // Synthesise a session so downstream middleware that reads
    // `res.locals.session.userId` (e.g. `enforceLimit` from
    // `@molecule/api-entitlements`) accepts the request. Semantically the
    // meter is acting on behalf of its owner — readings count against the
    // owner's tier quota, not against an anonymous identity.
    const existingSession = (res.locals.session as { userId?: string } | undefined) ?? {}
    res.locals.session = { ...existingSession, userId: row.user_id }

    // Best-effort last-used stamp; failure here must not block ingest.
    try {
      await updateById('meter_tokens', row.id, { last_used_at: new Date() })
    } catch (_error) {
      // swallow — last_used_at update is non-critical
    }
    next()
  } catch (_error) {
    // any unexpected lookup failure → 401 (no detail leak)
    res.status(401).json({
      error: t('readings.invalidToken', undefined, { defaultValue: 'Invalid meter token.' }),
    })
  }
}
